Request = (
  WsAddOrderMarket
  | WsAddOrderLimit
  | WsAddOrderIceberg
  | WsAddOrderStopLoss
  | WsAddOrderStopLossLimit
  | WsAddOrderTakeProfit
  | WsAddOrderTakeProfitLimit
  | WsAddOrderTrailingStop
  | WsAddOrderTrailingStopLimit
  | WsAddOrderSettlePosition
)


class AddOrder(SocketEndpoint):
  """Sends a single, new order into the exchange. A range of order types, Time-In-Force (TIF) settings and order flags can be specified. For triggered order types (`stop-loss`, `take-profit`, `trailing-stop`), `triggers` carries the price-tracking and trigger-threshold parameters. For One-Triggers-Other (OTO) orders, `conditional` carries the parameters for a secondary close order attached to the primary order."""

  async def add_order(
    self,
    order_request: Request,
    *,
    validate: bool | None = None,
  ) -> AddOrderResult:
    """Sends a single, new order into the exchange. A range of order types, Time-In-Force (TIF) settings and order flags can be specified. For triggered order types (`stop-loss`, `take-profit`, `trailing-stop`), `triggers` carries the price-tracking and trigger-threshold parameters. For One-Triggers-Other (OTO) orders, `conditional` carries the parameters for a secondary close order attached to the primary order.

    Args:
      order_request:
      validate: Override this call's response validation; falls back to the client-level default when omitted.

    References:
      - [Official docs](https://docs.kraken.com/exchange/api-reference/spot-websocket-v2/add_order)
    """
    return await self.request(
      order_request,
      path='add_order',
      validate=validate,
      request_type=Request,
      response_type=AddOrderResult,
    )
